Here's the complete updated `ContactSection.tsx` with client-side validation and inline error messages, matching the existing style:

```tsx
"use client"

import { useState } from "react"
import { SectionSep } from "@/components/ui/SectionHeader"
import { PROFILE } from "@/lib/content"

const META = [
  { label: "Email",        value: PROFILE.socials.email },
  { label: "Role",         value: "AI + Full-stack"     },
  { label: "Availability", value: PROFILE.status        },
  { label: "Response",     value: "Within 24 hours"     },
]

type FieldErrors = { name?: string; email?: string; message?: string }

function validate(form: { name: string; email: string; message: string }): FieldErrors {
  const errors: FieldErrors = {}
  if (!form.name.trim()) errors.name = "Name is required"
  if (!form.email.trim()) {
    errors.email = "Email is required"
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
    errors.email = "Enter a valid email address"
  }
  if (!form.message.trim()) errors.message = "Message is required"
  return errors
}

export function ContactSection() {
  const [form, setForm] = useState({ name: "", email: "", message: "" })
  const [errors, setErrors] = useState<FieldErrors>({})
  const [touched, setTouched] = useState<{ name?: boolean; email?: boolean; message?: boolean }>({})
  const [status, setStatus] = useState<"idle" | "loading" | "success" | "error">("idle")

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    const fieldErrors = validate(form)
    if (Object.keys(fieldErrors).length > 0) {
      setErrors(fieldErrors)
      setTouched({ name: true, email: true, message: true })
      return
    }
    setStatus("loading")
    try {
      const res = await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      })
      if (res.ok) { setStatus("success"); setForm({ name: "", email: "", message: "" }); setErrors({}) }
      else setStatus("error")
    } catch { setStatus("error") }
  }

  function handleChange(field: keyof typeof form, value: string) {
    const next = { ...form, [field]: value }
    setForm(next)
    if (touched[field]) {
      const fieldErrors = validate(next)
      setErrors(prev => ({ ...prev, [field]: fieldErrors[field] }))
    }
  }

  function handleBlur(field: keyof typeof form) {
    setTouched(prev => ({ ...prev, [field]: true }))
    const fieldErrors = validate(form)
    setErrors(prev => ({ ...prev, [field]: fieldErrors[field] }))
  }

  const inputStyle = (field: keyof typeof form): React.CSSProperties => ({
    width: "100%",
    minHeight: 46,
    border: `1px solid ${touched[field] && errors[field] ? "var(--color-error, #f87171)" : "var(--border-default)"}`,
    borderRadius: "var(--radius-sm)",
    background: "var(--bg)",
    color: "var(--text-primary)",
    padding: "12px 13px",
    fontSize: 14,
    outline: "none",
    fontFamily: "var(--font-sans)",
    transition: "border-color 180ms var(--ease-standard), background 180ms var(--ease-standard), box-shadow 180ms var(--ease-standard)",
    boxSizing: "border-box",
  })

  function onFocus(e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) {
    e.currentTarget.style.borderColor = "var(--border-hover)"
    e.currentTarget.style.background = "var(--surface-2)"
    e.currentTarget.style.boxShadow = "0 0 0 3px rgba(255,255,255,0.055)"
  }
  function onBlur(field: keyof typeof form) {
    return (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      const hasError = touched[field] && errors[field]
      e.currentTarget.style.borderColor = hasError ? "var(--color-error, #f87171)" : "var(--border-default)"
      e.currentTarget.style.background = "var(--bg)"
      e.currentTarget.style.boxShadow = "none"
      handleBlur(field)
    }
  }

  const errorStyle: React.CSSProperties = {
    fontSize: 11,
    color: "var(--color-error, #f87171)",
    margin: "4px 0 0",
    fontFamily: "var(--font-mono)",
  }

  const labelStyle: React.CSSProperties = {
    display: "block",
    fontSize: 11,
    color: "var(--text-faint)",
    fontFamily: "var(--font-mono)",
    textTransform: "uppercase",
    letterSpacing: "0.06em",
    marginBottom: 6,
  }

  return (
    <section id="contact" className="section">
      <SectionSep number="08" label="Contact" />
      <div className="section-content">
        <h2 className="section-title">Let&apos;s Build Something</h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 0.9fr) minmax(380px, 1.1fr)",
            gap: 16,
            alignItems: "start",
          }}
        >
          {/* Left — meta */}
          <div>
            <p style={{ fontSize: 15, color: "var(--text-secondary)", lineHeight: 1.7, margin: "0 0 28px" }}>
              Have an AI system, backend workflow, or project in mind? Send me a note.
            </p>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {META.map(({ label, value }) => (
                <div
                  key={label}
                  style={{
                    border: "1px solid var(--border-default)",
                    borderRadius: "var(--radius-md)",
                    background: "var(--surface-1)",
                    padding: 16,
                  }}
                >
                  <p style={{ fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", margin: "0 0 6px" }}>
                    {label}
                  </p>
                  <p style={{ fontSize: 13, color: "var(--text-secondary)", margin: 0 }}>{value}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Right — form */}
          <div
            style={{
              border: "1px solid var(--border-default)",
              borderRadius: "var(--radius-lg)",
              background: "var(--surface-1)",
              padding: 24,
            }}
          >
            {status === "success" ? (
              <div style={{ textAlign: "center", padding: "40px 0" }}>
                <p style={{ fontSize: 28, margin: "0 0 12px" }}>✓</p>
                <p style={{ fontSize: 15, color: "var(--text-primary)", margin: "0 0 6px", fontWeight: 500 }}>Message sent</p>
                <p style={{ fontSize: 13, color: "var(--text-muted)", margin: 0 }}>I&apos;ll get back to you within 24 hours.</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} noValidate style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                  <div>
                    <label style={labelStyle}>Name</label>
                    <input
                      type="text"
                      value={form.name}
                      onChange={e => handleChange("name", e.target.value)}
                      placeholder="Your name"
                      style={inputStyle("name")}
                      onFocus={onFocus}
                      onBlur={onBlur("name")}
                    />
                    {touched.name && errors.name && <p style={errorStyle}>{errors.name}</p>}
                  </div>
                  <div>
                    <label style={labelStyle}>Email</label>
                    <input
                      type="email"
                      value={form.email}
                      onChange={e => handleChange("email", e.target.value)}
                      placeholder="you@email.com"
                      style={inputStyle("email")}
                      onFocus={onFocus}
                      onBlur={onBlur("email")}
                    />
                    {touched.email && errors.email && <p style={errorStyle}>{errors.email}</p>}
                  </div>
                </div>
                <div>
                  <label style={labelStyle}>Message</label>
                  <textarea
                    value={form.message}
                    onChange={e => handleChange("message", e.target.value)}
                    placeholder="Tell me about your project..."
                    rows={5}
                    style={{ ...inputStyle("message"), resize: "vertical", minHeight: 132 }}
                    onFocus={onFocus}
                    onBlur={onBlur("message")}
                  />
                  {touched.message && errors.message && <p style={errorStyle}>{errors.message}</p>}
                </div>
                {status === "error" && (
                  <p style={{ fontSize: 12, color: "var(--text-muted)", margin: 0 }}>
                    Something went wrong — email me directly at {PROFILE.socials.email}
                  </p>
                )}
                <button
                  type="submit"
                  disabled={status === "loading"}
                  className="btn-primary"
                  style={{ opacity: status === "loading" ? 0.7 : 1, cursor: status === "loading" ? "wait" : "pointer" }}
                >
                  {status === "loading" ? "Sending…" : <>Send Message <span className="btn-arrow">→</span></>}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}
```

Key changes from the original:

- **`validate()`** — pure function returning `FieldErrors` for all three fields; email checked against a standard RFC-ish regex
- **`errors` + `touched` state** — errors only display after a field has been blurred or a submit was attempted, so the form doesn't yell at the user on first load
- **`handleChange`** — re-validates the relevant field live once it's been touched
- **`onBlur(field)`** — now returns a handler that marks the field touched, runs validation, and restores the border color (red on error, default otherwise)
- **`inputStyle(field)`** — dynamically sets `border-color` to `--color-error` (`#f87171` fallback) when a touched field has an error
- **`noValidate`** on the form — disables native browser validation bubbles so our inline messages are the only UX
- Submit is blocked and all fields marked touched if validation fails, revealing all errors at once
